import React, { Component } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, Alert, notification } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import queryString from 'query-string'
import { ContainerLayout, ContainerBody } from './index.style'
import validator from '../../../../../helpers/validator'
import { get } from 'lodash'
import { getFormItems } from '../../../../../components/utility/formItems'
import EndorseWelcome from '../ThankYouComponent'
import { ERROR_STRINGS } from '../../../../../constants/lang'

const { resetReduxPolicy, tokenizedDetailEndorsement, authorisedEndorsement } = policyAction

class FormContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      internalID: '',
      token: ''
    }
  }

  componentDidMount () {
    const { id } = this.props
    const internalId = get(id, 'match.params.id')
    const tokenObject = get(id, 'location.search', '')
    if (tokenObject) {
      const token = get(queryString.parse(tokenObject), 'token', '')
      if (token && internalId) {
        this.setState({
          internalId: internalId,
          token: token
        })
        this.props.tokenizedDetailEndorsement({
          query: {
            id: internalId,
            token: token
          }
        })
      }
    }
  }

  componentWillReceiveProps (nextProps) {
    const { policyEndorsementError, policyEndorsement, policyEndorsementMessage } = nextProps
    if (policyEndorsementMessage !== '' && policyEndorsementMessage !== 'success') {
      const errorData = get(policyEndorsement, 'error', '')
      if (!policyEndorsementError && (errorData && errorData !== 'success')) {
        if (Array.isArray(errorData)) {
          errorData.forEach(item => {
            if (get(item, 'key', '')) {
              this.props.form.setFields({
                [item.key]: {
                  value: item.val,
                  errors: [new Error(item.err)]
                }
              })
            } else {
              notification['error']({
                message: this.intlText({ id: 'Error' }),
                description: this.intlText({ id: item.err })
              })
            }
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        } else {
          notification['error']({
            message: this.intlText({ id: 'Error' }),
            description: this.intlText({ id: errorData })
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        }
      }
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }

  finalSubmit = async (e) => {
    e.preventDefault()
    const { internalId, token } = this.state
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()

    const payload = {
      ...formBody
    }
    delete payload.policy_number
    this.props.authorisedEndorsement({
      query: {
        internal_id: internalId,
        token: token
      },
      body: payload
    })
  }

  render () {
    const { getPolicyEndorsementDetailResult, policyEndorsementDetailLoading, policyEndorsementDetailError, policyEndorsementLoading, policyEndorsementMessage, header, subheading } = this.props
    const isSuccessFulEndorse = (policyEndorsementMessage === 'success') || get(getPolicyEndorsementDetailResult, 'EndorsementStatus') === 'SUCCESS'
    return (
      <ContainerLayout>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyEndorsementDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={policyEndorsementDetailLoading || policyEndorsementLoading}>
              <ContainerBody>
                <h3 className='form-heading'><b><IntlMessages id={header} /></b></h3>
                <p className='form-subheading'><IntlMessages id={subheading} /></p>
                <Form onSubmit={this.finalSubmit}>
                  <Row type='flex'>
                    <Col span={24}>
                      <Form.Item>
                        {
                          getFormItems.call(this, {
                            formName: 'policy_number',
                            type: 'alphanumeric',
                            label: 'Nomor Polis',
                            disableField: true,
                            initialValue: getPolicyEndorsementDetailResult ? get(getPolicyEndorsementDetailResult, 'InsurancePolicyNo', '') : '',
                            required: false
                          })
                        }
                      </Form.Item>
                    </Col>
                    <Col span={24}>
                      <Form.Item>
                        {
                          getFormItems.call(this, {
                            formName: 'address',
                            type: 'alphanumeric',
                            placeHolder: 'Tulis alamat penerima polis',
                            label: 'Alamat',
                            disableField: false,
                            initialValue: getPolicyEndorsementDetailResult ? get(getPolicyEndorsementDetailResult, 'Request.address', '') : '',
                            required: true,
                            validator: validator.validateAddress
                          })
                        }
                      </Form.Item>
                    </Col>
                    <Col span={24}>
                      <Form.Item>
                        {
                          getFormItems.call(this, {
                            formName: 'zipcode',
                            type: 'alphanumeric',
                            placeHolder: 'Tulis kode Pos',
                            label: 'Kode Pos',
                            disableField: false,
                            initialValue: getPolicyEndorsementDetailResult ? get(getPolicyEndorsementDetailResult, 'Request.zipcode', '') : '',
                            required: true,
                            validator: validator.validatePostalCode
                          })
                        }
                      </Form.Item>
                    </Col>
                    <Col span={24}>
                      <Button type='primary' htmlType='submit'><IntlMessages id='Kirim' /></Button>
                    </Col>
                  </Row>
                </Form>
              </ContainerBody>
            </CircularLoader>
        }
      </ContainerLayout>
    )
  }
}

FormContainer.defaultProps = {
  policyEndorsementLoading: false,
  policyEndorsementError: false,
  policyEndorsementDetailLoading: false,
  policyEndorsementDetailError: false
}
const ShopeeEndorsementWrapped = Form.create()(FormContainer)
export default connect(
  state => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT
  }),
  {
    resetReduxPolicy, tokenizedDetailEndorsement, authorisedEndorsement
  }
)(injectIntl(ShopeeEndorsementWrapped))
